def build_index(rows):
    def normalize(name):
        return name.strip().casefold()
    result = {}
    for row in rows:
        result.setdefault(normalize(row["name"]), row)
    return result

class Names {
    boolean fits(String name) {
        return name.length() <= 6;
    }
}
